      "그런데 이러한 움직임에 대해 나이 든 장인 중에는 눈살을 찌푸리는 사람도 있다. '옛날부터의 방식을 지켜야 비로소 전통이다. 팔린다고 해서 형태를 바꿔 버리면 그것은 더 이상 전통 공예가 아니다'라는 것이다. 새로운 제품만 주목받음으로써 본래의 종이 만드는 기술이 가볍게 여겨지지 않을까 걱정하는 목소리도 있다. 오랜 세월 하나의 기술을 갈고닦는 데 몰두해 온 사람의 말로서 그 마음은 이해할 수 있다.",
      "그러나 나는 전통이란 결코 변하지 않는 것을 말하는 것이 아니라고 생각한다. 애초에 지금은 '예로부터 내려온' 것이라 불리는 제품도 탄생 당시에는 사람들의 생활상의 필요에서 만들어진 새로운 도구였을 것이다. 시대가 바뀌고 사람들의 생활이 바뀌면 요구되는 형태도 바뀐다. 오히려 시대에 맞춰 조금씩 모습을 바꿔 왔기 때문에 전통은 수백 년이나 살아남을 수 있었던 것이 아닐까.",
      "물론 무엇이든 바꾸면 된다는 것은 아니다. 눈앞의 유행만 좇아 손이 많이 가는 공정을 생략해 버린다면 그야말로 전통은 사라지고 말 것이다. 지켜야 할 것은 제품의 형태 그 자체보다 그 안쪽에 있는 기술, 그리고 물건을 소중히 만든다는 장인의 마음일 것이다. 그것만 확실히 이어진다면 형태가 바뀌어도 전통은 사라지지 않는다. 옛것을 지키는 일과 새것을 만들어 내는 일. 이 둘은 대립하는 것이 아니라 전통을 다음 세대로 잇기 위한 수레의 두 바퀴인 것이다."
