      "心理学において「共感疲労」と呼ばれるこの状態は、単に個人の心が疲弊するにとどまらず、過剰な負荷から自己を守ろうとするあまり、かえって他者に対する極端な無関心や冷淡さを引き起こしかねない深刻な問題を孕んでいる。溢れ返る情動の奔流に呑み込まれることなく、真の意味で他者に寄り添い続けるためには、あえて一歩身を引き、自己の感情を客観的に見つめ直す理性の防壁が不可欠である。健全な精神的距離感を保つことによって初めて、私たちは自らの心の均衡を崩すことなく、必要な時に確固たる支援の手を差し伸べることができると言えよう。"
