    paragraphs: [
      "現代のグローバル市場において、企業のサステナビリティ経営やコンプライアンスの徹底は、単なる法令遵守の枠組みを超え、社会的な信頼を担保するための至上命題となっている。利益至上主義に偏重し、短期的な収益の獲得ばかりを優先してきた従来の経営スキームは、不正の隠蔽や不祥事の発生によって脆くも崩壊し、企業の存続そのものを揺るがしかねない。表面的なマニュアルを整えて満足する軽薄な姿勢を真摯に省みることなく、形式的なガバナンスに終始していては、組織の根底に潜む深刻な欠陥が世間に露呈するのは時間の問題である。",
      "真の持続可能性を達成するためには、多様なステークホルダーとの対話を絶え間なく重ね、業務のボトルネックとなっている旧態依然とした体質をドラスティックに改革する覚悟が不可欠だ。目先の利便性や甘い誘惑に流されることなく、自らの企業活動が社会に与える影響を深く顧みること。法令遵守を受動的な義務として捉えるのではなく、高い倫理観を携えて主体的に社会的責任を果たす姿勢こそが、企業の長期的な競争優位を確立し、ひいては社会全体の健全な発展に寄与する道にほかならない。"
    ],
    transParagraphs: [
      "현대 글로벌 시장에서 기업의 지속 가능성(서스테이너빌리티) 경영과 준법 감시(컴플라이언스)의 철저는 단순한 법령 준수의 틀을 넘어 사회적 신뢰를 담보하기 위한 지상 명제가 되고 있다. 이익 지상주의에 편중하여 단기적인 수익 획득만을 우선시해 온 기존의 경영 스킴(체계)은 부정의 은폐나 불미스러운 사건의 발생으로 맥없이 붕괴하여 기업의 존속 자체를 뒤흔들기 십상이다. 표면적인 매뉴얼을 갖추는 데 만족하는 경박한 태도를 진솔하게 반성(성찰)하지 않은 채 형식적인 거버넌스에 그쳐서는, 조직 근저에 도사린 심각한 결함이 세간에 노정(폭로)되는 것은 시간문제이다.",
      "진정한 지속 가능성을 달성하기 위해서는 다양한 이해관계자(스테이크홀더)와의 대화를 끊임없이 거듭하며, 업무의 병목(보틀넥)이 되고 있는 구태의연한 체질을 과감하고 근본적으로(드라스틱하게) 개혁할 각오가 필수적이다. 눈앞의 편의성이나 달콤한 유혹에 휩쓸리지 않고 자신의 기업 활동이 사회에 미치는 영향을 깊이 되돌아볼 것. 법령 준수를 수동적인 의무로 파악할 것이 아니라, 높은 윤리관을 지니고 주체적으로 사회적 책임을 다하는 태도야말로 기업의 장기적인 경쟁 우위를 확립하고, 나아가 사회 전체의 건전한 발전에 기여하는 길에 다름 아니다."
    ],
